import assert from'node:assert/strict';import path from'node:path';import{readFile,writeFile,mkdir,cp}from'node:fs/promises';import{constants}from'node:fs';import{load}from'cheerio';import{chromium}from'playwright';import{generate}from'../../engine/generate.mjs';import{extract}from'../../engine/extract.mjs';import{run}from'../../engine/pipeline.mjs';import{serveStatic}from'../../engine/static.mjs';
const root=path.resolve('artifacts/platform/events-heldout'),dest=path.join(root,'pagination-project');const model=JSON.parse(await readFile(path.join(root,'prepared-model.json')));const original=model.pages.find(p=>p.route==='/events/'),sourceStates=[];model.pages=model.pages.filter(p=>p.wordpress?.event);model.events.clock={timeZone:'America/New_York'};
for(const n of [1,2]){const html=await readFile(path.join(root,`list-config-source-page-${n}.html`),'utf8'),$=load(html),data=JSON.parse($('[data-js="tribe-events-view-data"]').first().text()),url=new URL(data.url);url.search='';const page=extract(html,url.href);page.styles=original.styles;model.pages.push(page);sourceStates.push({titles:$('.tribe-events-calendar-list__event-title').map((_,e)=>$(e).text().trim()).get(),labels:$('.tribe-events-c-top-bar__datepicker-time span').map((_,e)=>$(e).text().trim()).get(),dates:$('.tribe-events-c-top-bar__datepicker-time').map((_,e)=>$(e).attr('datetime')).get()});}
await mkdir(dest,{recursive:true});await cp(path.join(root,'project/assets'),path.join(dest,'assets'),{recursive:true,mode:constants.COPYFILE_FICLONE});await generate(model,dest);await run(process.execPath,['scripts/build.mjs'],{cwd:dest,timeout:120000});
let server,browser;const cases=[];try{server=await serveStatic(path.join(dest,'output'));browser=await chromium.launch({channel:'chrome'});for(const width of [1440,390]){const page=await browser.newPage({viewport:{width,height:900}});let requests=0;await page.route('**/*',r=>{if(new URL(r.request().url()).origin!==server.url){requests++;return r.abort();}return r.continue();});await page.goto(server.url+'/events/list/',{waitUntil:'networkidle'});const states=async()=>({titles:(await page.locator('.tribe-events-calendar-list__event-title').allTextContents()).map(x=>x.trim()),labels:(await page.locator('.tribe-events-c-top-bar__datepicker-time span').allTextContents()).map(x=>x.trim()),dates:await page.locator('.tribe-events-c-top-bar__datepicker-time').evaluateAll(es=>es.map(e=>e.getAttribute('datetime')))});await page.waitForFunction(()=>document.querySelector('.tribe-events-c-nav__next')?.dataset.calendarPage==='2');assert.deepEqual(await states(),sourceStates[0]);await page.locator('.tribe-events-c-nav__next').click();await page.waitForURL('**calendar-page=2');assert.deepEqual(await states(),sourceStates[1]);assert.equal(await page.locator('.tribe-events-c-nav__next').isDisabled(),true);await page.locator('.tribe-events-c-top-bar__datepicker-button').click();await page.locator('.datepicker').waitFor();assert.match(await page.locator('.datepicker-switch').textContent(),/July 2028/);await page.keyboard.press('Escape');await page.goBack();await page.waitForFunction(()=>document.querySelector('.tribe-events-c-nav__next')?.dataset.calendarPage==='2');assert.deepEqual(await states(),sourceStates[0]);await page.goto(server.url+'/events/list/?calendar-date=2028-01-01&calendar-page=2',{waitUntil:'networkidle'});assert.deepEqual(await states(),sourceStates[1]);await page.goto(server.url+'/events/list/?calendar-date=2028-07-01',{waitUntil:'networkidle'});assert.equal(await page.locator('.tribe-events-calendar-list__event-row').count(),2);assert.equal(await page.locator('.tribe-events-c-nav__next').isDisabled(),true);assert.equal(await page.locator('.tribe-events-c-nav__prev').isDisabled(),true);assert.equal(requests,0);cases.push({width,sourceHeadingsAndMembership:true,localNextPrevious:true,pickerUsesPageStart:true,history:true,deepLink:true,dateFilterResetsPage:true,externalRequests:requests});await page.close();}await writeFile(path.join(root,'paginated-generated-check.json'),JSON.stringify({scope:'Native project generated from installed two-page source captures and cached event records/assets; no new source crawl or AI; full visual audit not run',cases},null,2)+'\n');console.log(JSON.stringify({cases}));}finally{await browser?.close();await server?.close();}
